using System.Windows;using AutoPecasERP.Core.Entities;using AutoPecasERP.Data.Context;using AutoPecasERP.Services.Oficina;using Microsoft.EntityFrameworkCore;
namespace AutoPecasERP.Desktop.Views;
public partial class NovaOsWindow:Window{readonly ErpDbContext _db=new();readonly Usuario _u;public NovaOsWindow(Usuario u){InitializeComponent();_u=u;Loaded+=async(_,__)=>ClienteBox.ItemsSource=await _db.Clientes.Where(x=>x.Ativo).OrderBy(x=>x.Nome).ToListAsync();}
async void Cliente_Changed(object s,System.Windows.Controls.SelectionChangedEventArgs e){if(ClienteBox.SelectedItem is Cliente c)VeiculoBox.ItemsSource=await _db.VeiculosCliente.Where(x=>x.ClienteId==c.Id).ToListAsync();}
async void NovoVeiculo_Click(object s,RoutedEventArgs e){if(ClienteBox.SelectedItem is not Cliente c){MessageBox.Show("Selecione o cliente primeiro.");return;}var d=new NovoVeiculoWindow(c.Id){Owner=this};if(d.ShowDialog()==true)VeiculoBox.ItemsSource=await _db.VeiculosCliente.Where(x=>x.ClienteId==c.Id).ToListAsync();}
async void Salvar_Click(object s,RoutedEventArgs e){if(ClienteBox.SelectedItem is not Cliente c){MessageBox.Show("Selecione o cliente.");return;}if(string.IsNullOrWhiteSpace(ProblemaBox.Text)){MessageBox.Show("Informe o problema relatado.");return;}int.TryParse(KmBox.Text,out var km);var v=VeiculoBox.SelectedItem as VeiculoCliente;var os=await new OficinaService(_db).AbrirAsync(c.Id,v?.Id,km,ProblemaBox.Text,MecanicoBox.Text);os.Diagnostico=DiagnosticoBox.Text;await _db.SaveChangesAsync();DialogResult=true;}}